import openpyxl, json
wb = openpyxl.load_workbook('delivery.xlsx', data_only=False)
print('sheets', wb.sheetnames)
for ws in wb.worksheets:
    print('---', ws.title, ws.dimensions, ws.max_row, ws.max_column)
    for row in ws.iter_rows(min_row=1, max_row=min(ws.max_row,14), max_col=min(ws.max_column,6)):
        out=[]
        for c in row:
            if c.value is not None:
                out.append(f'{c.coordinate}={c.value!r}')
        if out: print(' | '.join(out))
print('=== cached values ===')
